answer = (function transformEntry(source) {

    // Safely get the value from the staging table
    var rawValue = source.u_time_sid ? source.u_time_sid.toString() : "";

    // Remove commas, decimals, and any non-numeric characters
    var cleanValue = rawValue.replace(/[^0-9]/g, '');

    // Must be a valid 8-digit date (YYYYMMDD)
    if (cleanValue.length >= 8) {
        var datePart = cleanValue.substring(0, 8);

        var year = parseInt(datePart.substring(0, 4), 10);
        var month = parseInt(datePart.substring(4, 6), 10); // 1-12

        // JS Date trick: day 0 of "next month" = last day of "this month"
        // new Date(year, month, 0) -> month here is already 1-based next-month index
        var lastDay = new Date(year, month, 0).getDate();

        var mm = (month < 10 ? "0" : "") + month;
        var dd = (lastDay < 10 ? "0" : "") + lastDay;

        // Always returns the true calendar month-end, e.g. 20260731, 20260228, 20260229 (leap year)
        return "" + year + mm + dd;
    }

    // Return empty string if the row is blank or invalid so it doesn't error out
    return "";

})(source);
